const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const args = source.args || payload.args || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || source.text || source.targetName || args.targetName || source.folderName || args.folderName || args.name || payload.targetName || payload.folderName || payload.text || '').trim();
const folderName = String(source.folderName || source.targetName || source.name || args.folderName || args.targetName || args.name || payload.folderName || payload.targetName || raw.replace(/^(tao folder|tao thu muc|create folder)\s*/i, '')).trim();
const folderId = String(source.folderId || source.targetFolderId || source.parentId || args.folderId || args.targetFolderId || args.parentId || payload.folderId || payload.targetFolderId || 'root').trim() || 'root';
return [{ json: { ...source, payload, message, chatId, raw, folderName, targetName: folderName, folderId, targetFolderId: folderId, hasTarget: Boolean(folderName), response: folderName ? '' : '📁 <b>Tao folder</b>\n\nVi du: tao folder Khach hang' } }];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const source = $('Prepare Action').item.json || {};
const item = $input.item.json || {};

const folderName = pickFirst(item.name, source.folderName, 'Không rõ tên');
const folderId = pickFirst(item.id, item.fileId);
const link = pickFirst(item.webViewLink, item.webContentLink) || (folderId ? `https://drive.google.com/drive/folders/${folderId}` : '');

let text = '✅ <b>Đã tạo folder Google Drive</b>\n\n';

text += `📁 <b>${escapeHtml(folderName)}</b>\n`;

if (folderId) {
  text += `ID: <code>${escapeHtml(folderId)}</code>\n`;
}

if (link) {
  text += `🔗 <a href="${escapeHtml(link)}">Mở folder</a>\n`;
}

return [{
  json: {
    chatId: source.chatId,
    text: text.trim(),
  },
}];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
